use chrono::Local;
use std::io::Write;

use super::truncate::truncate_str;
use crate::application::DoctorReport;
use crate::domain::{
    ActivityCapabilities, ActivityObservation, FreshnessState, IdleState, SourceHealth,
};

/// Prints the detailed diagnostic report generated by `flowguard doctor`.
pub fn print_doctor_report(report: &DoctorReport, _verbose: bool) {
    println!();
    println!("=== FlowGuard Doctor: ActivityWatch Integration Diagnostics ===");
    println!();

    // 1. Endpoint & Handshake
    println!("Activity Source Configuration:");
    println!("  Endpoint URL:        {}", report.endpoint);
    println!(
        "  Reachable:           {}",
        if report.is_reachable { "Yes" } else { "NO" }
    );
    println!(
        "  Service Identity:    {}",
        if report.is_activitywatch {
            "ActivityWatch"
        } else {
            "UNKNOWN / WRONG SERVICE"
        }
    );

    if let Some(ref info) = report.server_info {
        println!("  Server Version:      {}", info.version);
        println!("  Server Hostname:     {}", info.hostname);
        println!(
            "  Testing Mode:        {}",
            if info.testing {
                "YES (Separate dev database)"
            } else {
                "No (Production)"
            }
        );
        if let Some(ref profile) = info.profile {
            println!("  Server Profile:      {}", profile);
        }
    }
    println!();

    // 2. Discovered Buckets
    println!(
        "Discovered Watcher Buckets (Total: {}):",
        report.buckets_count
    );
    print_bucket_line(
        "Desktop Window",
        report.window_bucket.as_deref(),
        report.window_freshness,
    );
    print_bucket_line(
        "User Idle / AFK",
        report.afk_bucket.as_deref(),
        report.idle_freshness,
    );
    print_bucket_line(
        "Browser Tab",
        report.web_bucket.as_deref(),
        report.browser_freshness,
    );
    println!();

    // 3. Capabilities
    println!("Detected Capabilities:");
    print_capability(
        "Application Tracking",
        report.capabilities.application_tracking,
    );
    print_capability(
        "Window Title Tracking",
        report.capabilities.window_title_tracking,
    );
    print_capability("User Idle Detection", report.capabilities.idle_tracking);
    print_capability(
        "Browser URL Tracking",
        report.capabilities.browser_url_tracking,
    );
    print_capability(
        "Incognito Detection",
        report.capabilities.incognito_detection,
    );
    println!();

    // 4. Operational Health
    println!("Overall Source Health: {}", format_health(report.health));
    println!();

    // 5. Diagnostics & Advice
    if !report.diagnostics.is_empty() {
        println!("Diagnostics & Warnings:");
        for diag in &report.diagnostics {
            println!("  [!] {}", diag);
        }
        println!();
    }

    if !report.is_reachable {
        if report.health == SourceHealth::WrongService {
            println!("Troubleshooting advice:");
            println!("  Another application is occupying port 5600, or ActivityWatch is running on a different port.");
            println!("  Check if ActivityWatch is running on a custom port, and set `base_url` in config/flowguard.toml.");
        } else {
            println!("Troubleshooting advice:");
            println!("  1. Ensure ActivityWatch is installed and running on your machine.");
            println!("  2. Start ActivityWatch via the Windows Start Menu or run `aw-qt.exe`.");
            println!(
                "  3. Confirm the ActivityWatch web UI is accessible at: {}",
                report.endpoint
            );
        }
        println!();
    } else if report.window_freshness == FreshnessState::Stale {
        println!("Troubleshooting advice:");
        println!("  ActivityWatch server is running, but `aw-watcher-window` has stopped producing fresh events.");
        println!("  Restart ActivityWatch or verify that aw-watcher-window.exe is active in Task Manager.");
        println!();
    }

    println!("Privacy Guarantee:");
    println!("  FlowGuard runs 100% locally on your machine. No telemetry, screenshots, or cloud syncing.");
    println!();
}

fn print_bucket_line(label: &str, bucket_id: Option<&str>, freshness: FreshnessState) {
    let status_badge = match freshness {
        FreshnessState::Fresh => "[Fresh]",
        FreshnessState::Stale => "[STALE]",
        FreshnessState::Missing => "[Missing / Inactive]",
    };

    match bucket_id {
        Some(id) => println!("  - {:<18} : {} {}", label, id, status_badge),
        None => println!("  - {:<18} : Not Found {}", label, status_badge),
    }
}

fn print_capability(label: &str, available: bool) {
    let badge = if available {
        "Available"
    } else {
        "Unavailable"
    };
    println!("  - {:<24} : {}", label, badge);
}

fn format_health(health: SourceHealth) -> &'static str {
    match health {
        SourceHealth::Connecting => "Connecting...",
        SourceHealth::Connected => "Connected (Healthy)",
        SourceHealth::Degraded => "Degraded (Reachable, but watchers missing or stale)",
        SourceHealth::Disconnected => "Disconnected (Service unreachable)",
        SourceHealth::WrongService => "Wrong Service (Port occupied by another application)",
    }
}

/// Prints current health and capabilities summary for `flowguard status`.
pub fn print_status(health: SourceHealth, caps: &ActivityCapabilities, endpoint: &str) {
    println!();
    println!("FlowGuard Status:");
    println!("  Endpoint:     {}", endpoint);
    println!("  Health:       {}", format_health(health));
    println!(
        "  Capabilities: AppTracking: {}, TitleTracking: {}, Idle: {}, WebURL: {}",
        if caps.application_tracking {
            "Yes"
        } else {
            "No"
        },
        if caps.window_title_tracking {
            "Yes"
        } else {
            "No"
        },
        if caps.idle_tracking { "Yes" } else { "No" },
        if caps.browser_url_tracking {
            "Yes"
        } else {
            "No"
        }
    );
    println!();
}

/// Prints a single normalized activity observation for `flowguard observe --once`.
pub fn print_observation_snapshot(obs: &ActivityObservation, verbose: bool) {
    println!();
    println!("=== Activity Observation Snapshot ===");
    println!(
        "Observed At:     {}",
        obs.observed_at
            .with_timezone(&Local)
            .format("%Y-%m-%d %H:%M:%S")
    );
    println!("Source Health:   {}", format_health(obs.source_health));
    println!("Idle State:      {}", obs.idle_state.as_str());

    println!(
        "Application:     {}",
        obs.application.as_deref().unwrap_or("[Unknown / None]")
    );

    let title_display = match &obs.window_title {
        Some(title) => {
            if verbose {
                title.clone()
            } else {
                truncate_str(title, 60)
            }
        }
        None => "[Unavailable]".to_string(),
    };
    println!("Window Title:    {}", title_display);

    if let Some(ref browser) = obs.browser {
        let url_display = match &browser.url {
            Some(u) => {
                if verbose {
                    u.clone()
                } else {
                    let sanitized = sanitize_url(u);
                    truncate_str(&sanitized, 60)
                }
            }
            None => "[Not reported]".to_string(),
        };
        println!("Browser URL:     {}", url_display);

        let browser_title_display = match &browser.title {
            Some(t) => {
                if verbose {
                    t.clone()
                } else {
                    truncate_str(t, 60)
                }
            }
            None => "[Not reported]".to_string(),
        };
        println!("Browser Tab:     {}", browser_title_display);

        println!(
            "Audio Playing:   {}",
            browser
                .audible
                .map(|a| if a { "Yes" } else { "No" })
                .unwrap_or("Unknown")
        );
        println!(
            "Incognito:       {}",
            browser
                .incognito
                .map(|i| if i { "Yes" } else { "No" })
                .unwrap_or("Unknown")
        );
    } else {
        println!("Browser Context: [Unavailable - Extension watcher not present or inactive]");
    }

    println!(
        "Freshness:       Window: {}, Idle: {}, Browser: {}",
        obs.window_freshness.as_str(),
        obs.idle_freshness.as_str(),
        obs.browser_freshness.as_str()
    );

    if !obs.diagnostics.is_empty() {
        println!("Diagnostics:");
        for d in &obs.diagnostics {
            println!("  - {}", d);
        }
    }
    println!();
}

/// Prints a compact single-line update when an observation change occurs in `flowguard observe`.
pub fn print_observation_change(obs: &ActivityObservation, verbose: bool) {
    let time_str = obs.observed_at.with_timezone(&Local).format("%H:%M:%S");

    let idle_badge = match obs.idle_state {
        IdleState::Active => "[ACTIVE]",
        IdleState::Afk => "[AFK   ]",
        IdleState::Unknown => "[?IDLE ]",
    };

    let app = obs.application.as_deref().unwrap_or("-");

    let title = match &obs.window_title {
        Some(t) => {
            if verbose {
                t.clone()
            } else {
                truncate_str(t, 40)
            }
        }
        None => "-".to_string(),
    };

    let browser_info = if let Some(ref b) = obs.browser {
        if let Some(ref u) = b.url {
            let display_url = if verbose {
                u.clone()
            } else {
                let sanitized = sanitize_url(u);
                truncate_str(&sanitized, 60)
            };
            format!(" | url: {}", display_url)
        } else {
            String::new()
        }
    } else {
        String::new()
    };

    let health_suffix = if obs.source_health != SourceHealth::Connected {
        format!(" ({})", obs.source_health.as_str())
    } else {
        String::new()
    };

    println!(
        "[{}] {} {} — \"{}\"{}{}",
        time_str, idle_badge, app, title, browser_info, health_suffix
    );
    std::io::stdout().flush().ok();
}

/// Sanitizes a URL for privacy by displaying domain and path prefix, omitting sensitive query params.
fn sanitize_url(url: &str) -> String {
    match url.split_once('?') {
        Some((base, _)) => format!("{}?[query-redacted]", base),
        None => url.to_string(),
    }
}
